#include <stdio.h>
#include <stdlib.h>

// Assuming the following structures and functions are defined elsewhere:
// struct block_device;
// struct super_block;
// struct block_device *bdev_get_by_dev(dev_t dev);
// int blkdev_open(struct block_device *bdev, int flags);
// void bdev_put(struct block_device *bdev);

struct block_device *get_block_device(dev_t dev, struct super_block *sb) {
    struct block_device *bdev = bdev_get_by_dev(dev);
    if (!bdev) {
        // Failed to retrieve the block device
        return NULL;
    }

    // Open the block device with read, write, and exclusive access modes
    int result = blkdev_open(bdev, O_RDWR | O_EXCL);
    if (result != 0) {
        // Failed to open the block device
        bdev_put(bdev);
        return NULL;
    }

    return bdev;
}
